ALTER TABLE public.vendor_registrations ADD COLUMN user_id uuid;
CREATE UNIQUE INDEX vendor_registration_user ON public.vendor_registrations(user_id) WHERE user_id IS NOT NULL;
ALTER TABLE public.products ADD COLUMN vendor_id uuid REFERENCES public.vendor_registrations(id);
ALTER TABLE public.orders ADD COLUMN payment_status text NOT NULL DEFAULT 'unpaid';
ALTER TABLE public.orders ADD CONSTRAINT orders_payment_status_valid CHECK (payment_status IN ('unpaid','paid','refunded'));
CREATE POLICY "company reads own registration" ON public.vendor_registrations FOR SELECT TO authenticated USING (user_id = auth.uid());
DROP POLICY "anyone can register" ON public.vendor_registrations;
CREATE POLICY "anyone can register" ON public.vendor_registrations FOR INSERT TO anon,authenticated WITH CHECK (status = 'pending' AND (user_id IS NULL OR user_id = auth.uid()) AND length(company_name) BETWEEN 1 AND 200 AND length(contact_name) BETWEEN 1 AND 200 AND length(email) BETWEEN 3 AND 255 AND length(phone) BETWEEN 5 AND 30 AND length(payment_reference) BETWEEN 3 AND 100);
CREATE FUNCTION public.can_manage_vendor(_vendor_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.vendor_registrations WHERE id = _vendor_id AND user_id = auth.uid() AND status IN ('paid','approved')); $$;
REVOKE ALL ON FUNCTION public.can_manage_vendor(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_manage_vendor(uuid) TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.products TO authenticated;
CREATE POLICY "company inserts own products" ON public.products FOR INSERT TO authenticated WITH CHECK (public.can_manage_vendor(vendor_id) AND length(name) BETWEEN 1 AND 200 AND price >= 0);
CREATE POLICY "company updates own products" ON public.products FOR UPDATE TO authenticated USING (public.can_manage_vendor(vendor_id)) WITH CHECK (public.can_manage_vendor(vendor_id) AND length(name) BETWEEN 1 AND 200 AND price >= 0);
CREATE POLICY "company deletes own products" ON public.products FOR DELETE TO authenticated USING (public.can_manage_vendor(vendor_id));
CREATE FUNCTION public.validate_registration_fee() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN NEW.fee_amount := COALESCE((SELECT NULLIF(value,'')::numeric FROM public.store_settings WHERE key='vendor_fee'),0); RETURN NEW; END; $$;
CREATE TRIGGER registration_fee_from_settings BEFORE INSERT ON public.vendor_registrations FOR EACH ROW EXECUTE FUNCTION public.validate_registration_fee();
CREATE FUNCTION public.validate_order_payment() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND NEW.payment_status <> 'unpaid' THEN RAISE EXCEPTION 'Only administrators can record payment'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER order_payment_on_insert BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.validate_order_payment();